from pathlib import Path
import html
root=Path(__file__).resolve().parent
preview=root/'preview'

def icon(name):
 paths={
 'arrow':'<path d="M4 12h16"/><path d="m13 5 7 7-7 7"/>',
 'upRight':'<path d="M7 17 17 7M7 7h10v10"/>',
 'chart':'<path d="M3 3v18h18"/><path d="m7 16 4-5 4 3 5-8"/>',
 'database':'<ellipse cx="12" cy="5" rx="9" ry="3"/><path d="M3 5v14c0 1.7 4 3 9 3s9-1.3 9-3V5M3 12c0 1.7 4 3 9 3s9-1.3 9-3"/>',
 'check':'<path d="m5 12 4 4L19 6"/>',
 'grid':'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
 'layers':'<path d="m12 2 9 5-9 5-9-5 9-5Z"/><path d="m3 12 9 5 9-5M3 17l9 5 9-5"/>',
 'shield':'<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z"/><path d="m9 12 2 2 4-4"/>',
 'spark':'<path d="m12 3 1.8 6.2L20 11l-6.2 1.8L12 19l-1.8-6.2L4 11l6.2-1.8L12 3Z"/>',
 'code':'<path d="m8 8-4 4 4 4M16 8l4 4-4 4M14 4l-4 16"/>',
 'github':'<path d="M9 19c-4 1-4-2-6-2m12 4v-3.1a3.1 3.1 0 0 0-.8-2.4c2.7-.3 5.5-1.3 5.5-6A4.8 4.8 0 0 0 18.4 6 4.4 4.4 0 0 0 18.3 3S17 2.7 15 4.4a11 11 0 0 0-6 0C7 2.7 5.7 3 5.7 3a4.4 4.4 0 0 0-.1 3A4.8 4.8 0 0 0 4.3 9.5c0 4.7 2.8 5.7 5.5 6A3.1 3.1 0 0 0 9 18v3"/>',
 'back':'<path d="m12 19-7-7 7-7M5 12h15"/>',
 }
 return f'<svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{paths.get(name,paths["spark"])}</svg>'

def start(title,base):
 return f'''<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{html.escape(title)} · Jane Allyson Paray</title><meta name="description" content="Jane Allyson Paray, aspiring IT professional with interests in data analytics, business analysis and software QA."><link rel="stylesheet" href="{base}src/styles.css"><style>.static-preview-note{{position:fixed;bottom:14px;right:14px;z-index:90;background:#24243b;color:white;border-radius:12px;box-shadow:0 8px 30px #0003;padding:10px 15px;font:600 12px system-ui;max-width:230px;line-height:1.4}}</style></head><body>'''

def header(base):return f'''<header class="site-header"><div class="container nav-wrap"><a class="brand" href="{base}preview/index.html"><span class="brand-mark">j<span class="brand-star">✳</span></span><span>jane<span class="brand-dot">.</span></span></a><nav aria-label="Primary navigation" class="top-nav"><a href="{base}preview/index.html#work">Work</a><a href="{base}preview/index.html#about">About</a><a href="{base}preview/index.html#contact">Contact</a></nav><div class="nav-actions"><a class="btn btn-quiet nav-resume" href="{base}preview/index.html#work">Explore work {icon('upRight')}</a></div></div></header>'''

def footer():return '<footer class="site-footer"><div class="container footer-inner"><span>Made thoughtfully, one iteration at a time ✳</span><span>© 2026 Jane Allyson Paray</span><a href="#top">Back to top ↑</a></div></footer>'

def end():return '<div class="static-preview-note">Offline design preview • React source is in the parent project</div></body></html>'

def kicker(x):return f'<span class="eyebrow"><span class="eyebrow-dash"></span>{x}</span>'

def tags(arr):return '<div class="tag-row">'+''.join('<span class="tag">'+x+'</span>' for x in arr)+'</div>'

def project_card(base,d):
 name='DISTYNC' if d else 'Campus Lost & Found'
 href=base+'preview/projects/distync/index.html' if d else base+'preview/projects/lost-and-found/index.html'
 if d:
  img='<div class="preview preview-distync"><div class="preview-grain"></div><div class="preview-label">DISTYNC / SYSTEM OVERVIEW</div><div class="preview-flow"><span>Registration</span><b>→</b><span>Distribution</span><b>→</b><span>Monitoring</span></div><div class="preview-graphic"><div class="mini-orbit orbit-a"></div><div class="mini-orbit orbit-b"></div><div class="preview-core">'+icon('layers')+'</div></div><div class="preview-note">Connecting relief operations across offices</div></div>'
  txt='Bringing disaster-relief records, distribution workflows, inventory, and analytics into one connected system.'
  meta='01 / TEAM CAPSTONE'
  tag=['Analytics','Business Analysis','Software QA']
 else:
  panels=''.join(f'<div class="lf-panel"><div class="lf-panel-icon">{icon(i)}</div><span>{text}</span><span class="lf-trailing">{n:02}</span></div>' for n,(i,text) in enumerate([('grid','Report an item'),('chart','Browse listings'),('check','Submit a claim')],1))
  img='<div class="preview preview-lost"><div class="preview-label">CAMPUS LOST & FOUND / USER JOURNEY</div>'+panels+'<div class="preview-note">A thoughtful flow to reunite people and belongings</div></div>'
  txt='A full-stack application helping campus communities report, find, and claim belongings—with AI-assisted report review.'
  meta='02 / INDIVIDUAL PROJECT';tag=['Full-stack','API Integration','Testing']
 return f'<article class="project-card"><a class="project-card-link" href="{href}">{img}<div class="project-body"><div class="project-meta"><span>{meta}</span>{icon("upRight")}</div><h3>{name}</h3><p>{txt}</p>{tags(tag)}</div></a></article>'

base='../'
hero=f'''<main id="top"><section class="hero container"><div class="hero-copy">{kicker('HELLO, I\'M JANE ✦')}<h1>Curious about <span class="highlight-blue">data.</span><br>Passionate about <span class="highlight-purple">better systems.</span></h1><p>I'm Jane Allyson Paray, an Information Technology student specializing in Systems Development. I love exploring how data, people, and technology connect—from understanding a workflow to building and testing solutions that make sense.</p><div class="hero-actions"><a class="btn btn-primary" href="#work">Explore my work {icon('arrow')}</a><a class="btn btn-outline" href="projects/distync/index.html">Featured case study {icon('arrow')}</a></div><div class="hero-id"><div class="avatar-placeholder"><span>j.</span><i>✦</i></div><div><span class="hero-id-title">Jane Allyson Paray</span><span class="hero-id-sub">Aspiring IT professional · Based in the Philippines</span></div><span class="id-spark">✳</span></div></div><div class="hero-aside"><div class="hero-orbit orbit-one"></div><div class="hero-orbit orbit-two"></div><div class="hero-orbit orbit-three"></div><div class="aside-content"><span class="aside-overline">A LITTLE BIT ABOUT MY APPROACH</span><span class="aside-big">Observe.<br><i>Understand.</i><br>Improve.</span><div class="aside-rule"></div><div class="aside-bottom"><span>Curiosity meets<br>thoughtful execution.</span><div class="aside-icon">{icon('spark')}</div></div></div></div></section>'''
work=f'''<section class="section container work-section" id="work"><div class="section-top"><div>{kicker('01 / SELECTED WORK')}<h2>A few things I've worked on.</h2><p class="section-intro">Two projects, different challenges—and lots of learning along the way.</p></div></div><div class="project-grid">{project_card('../',True)}{project_card('../',False)}</div></section>'''
spotlight=f'''<section class="spotlight-section" id="analytics"><div class="container spotlight-grid"><div class="spotlight-copy">{kicker('03 / A CLOSER LOOK')}<h2>Making operational data <em>more useful.</em></h2><p>In DISTYNC, our team explored how everyday records could support better relief planning. The work brings together barangay-level descriptive analytics and inventory forecasting with historical model evaluation.</p><div class="spotlight-bullets"><span>{icon('check')}Barangay-level operational heat map</span><span>{icon('check')}Moving Average, Exponential Smoothing & Trend Projection</span><span>{icon('check')}Model evaluation using MAE and RMSE</span></div><a class="text-link" href="projects/distync/index.html#analytics">Explore the analytics work {icon('arrow')}</a></div><div class="data-panel"><div class="data-panel-top"><span class="data-panel-chip">DATA → DECISIONS</span>{icon('chart')}</div><div class="data-placeholder"><div class="data-sequence"><span>{icon('database')} Records</span>{icon('arrow')}<span>{icon('grid')} Aggregation</span>{icon('arrow')}<span>{icon('chart')} Insight</span></div><div class="data-place-note">Real heat-map screenshot to be added after final asset review</div></div><p class="data-footnote">Data visualization is a tool for understanding operations—not a substitute for field validation.</p></div></div></section>'''
caps=[('data','chart','Data & insight','SQL, relational databases, descriptive analytics, forecasting concepts, reporting and interpretation.'),('systems','layers','Business & systems','Requirements gathering, workflow analysis, functional requirements, documentation and stakeholder collaboration.'),('quality','shield','Quality & development','Functional tests, UAT, defect review, React, TypeScript, Express and API integration.'),('explore','spark','Always exploring','Coursework and hands-on exploration in networking, UiPath, Power Apps, Linux, Windows Server and cloud.')]
skills=f'''<section class="section container skills-section"><div class="section-top"><div>{kicker('04 / WHAT I BRING')}<h2>How I like to solve problems.</h2><p class="section-intro">A mix of analysis, building, testing, and curiosity about how things work behind the scenes.</p></div></div><div class="capabilities-grid">'''+''.join(f'<div class="capability cap-{kind}"><div class="cap-icon">{icon(ic)}</div><h3>{title}</h3><p>{txt}</p></div>' for kind,ic,title,txt in caps)+'</div></section>'
about=f'''<section class="section container about-section" id="about"><div class="about-panel"><div>{kicker('05 / BEYOND THE SCREEN')}<h2>A little more<br><em>about me.</em></h2></div><div class="about-content"><p>I'm studying BS Information Technology, specializing in Systems Development, at De La Salle Lipa (expected June 2027). I'm especially interested in opportunities where I can work with data, understand user needs, and help deliver dependable software.</p><p>Working with project teammates, advisers, and stakeholders has taught me that listening, clear communication, and being open to feedback matter just as much as technical skills.</p><div class="about-cards"><span><strong>Beyond coursework</strong>JPCS student leadership & collaboration</span><span><strong>What motivates me</strong>Learning, thoughtful problem-solving & useful technology</span></div></div></div></section>'''
contact=f'''<section class="contact-section" id="contact"><div class="container contact-panel"><div>{kicker('LET\'S CONNECT ✳')}<h2>Have a project, problem,<br>or opportunity in mind?</h2><p>I'm looking for an internship where I can contribute, learn from experienced people, and keep growing in data, analysis, software quality, and systems work.</p></div><div class="contact-actions"><a class="btn btn-light" href="https://github.com/JaneAllysonParay" target="_blank" rel="noopener noreferrer">{icon('github')} Find me on GitHub {icon('upRight')}</a><span class="contact-note">Professional email, LinkedIn and resume links will be added before launch.</span></div><span class="contact-deco">✳</span></div></section>'''
(preview/'index.html').write_text(start('Portfolio',base)+header(base)+hero+work+spotlight+skills+about+contact+'</main>'+footer()+end())


def study_header(name,title,desc,theme,tagslist):return f'<div class="study-hero study-{theme}">{kicker(name)}<h1>{title}</h1><p>{desc}</p>{tags(tagslist)}</div>'
def breadcrumb(base,name):return f'<div class="breadcrumb"><a href="{base}preview/index.html#work">{icon("back")} Back to work</a><span>/</span><span>{name}</span></div>'
def detail_section(k,title,inner,id=''):return f'<section class="study-section" '+(f'id="{id}"' if id else '')+f'>{kicker(k)}<h2>{title}</h2>{inner}</section>'

base='../../../'
distync=study_header('01 / TEAM CAPSTONE','DISTYNC: Connecting people, records, and relief operations.','A multi-office disaster relief management system designed to make fragmented data and workflows easier to monitor—while respecting established LGU procedures.','blue',['Data analytics','Business analysis','Quality assurance','Systems development'])
distync+= '<div class="study-overview"><div><span class="small-label">PROJECT TYPE</span><strong>Team capstone</strong></div><div><span class="small-label">FOCUS</span><strong>LGU disaster relief workflows</strong></div><div><span class="small-label">STACK</span><strong>React · Express · PostgreSQL · Python</strong></div></div><div class="study-grid"><article class="study-body">'
distync+=detail_section('01 / CONTEXT','The challenge','<p>Disaster-relief operations involve coordinated work across barangays, the MSWDO, and the Office of the Mayor. Paper forms, spreadsheets, and separate records made household monitoring, distribution tracking, and inventory reconciliation harder to consolidate.</p><p>Our team developed DISTYNC, a centralized role-based Progressive Web Application (PWA) that connects those workflows with reporting, descriptive analytics, and selected offline support.</p>')
distync+=detail_section('02 / MY PART IN THE TEAM','Where I contributed','<div class="contribution-list"><div><span>01</span><p><strong>Requirements & systems thinking.</strong> Participated in requirements refinement, data dictionary work, architecture planning, technical documentation, and stakeholder discussions.</p></div><div><span>02</span><p><strong>Technology & implementation.</strong> Researched technology choices, established the PostgreSQL database hosted by Supabase, helped start AI-assisted development, and worked on the Mayor\'s forecasting feature using AI assistance.</p></div><div><span>03</span><p><strong>Validation & communication.</strong> Helped prepare and execute testing, assisted with stakeholder demonstrations and UAT, reviewed findings, and contributed to final presentations.</p></div></div>')
distync+=detail_section('03 / BUSINESS ANALYSIS','How the operations connect',f'''<p>The MSWDO creates the disaster-event context, barangay officials register households and verify relief claims, and DISTYNC records accepted distributions and their inventory effects. The Mayor's Office maintains stock and relief-pack templates in parallel. Successful records and synchronization support monitoring.</p><div class="workflow-card"><div class="workflow-card-top"><strong>High-level operational workflow</strong><a class="diagram-open" href="../../diagrams/distync-flow.svg" target="_blank">Open full diagram</a></div><div class="workflow-image-viewport"><img src="../../diagrams/distync-flow.svg" alt="MSWDO disaster event flows to Barangay registration, stub, claim, distribution, and monitoring with parallel inventory preparation."></div><p>Based on documented use cases. Offline work is centrally accepted only after successful synchronization.</p></div>''','workflow')
distync+=detail_section('04 / DATA ANALYTICS','Turning records into insight','<p><strong>Descriptive analytics:</strong> Barangay operational heat map shows aggregated operational indicators—not household locations or hazard predictions.</p><p><strong>Forecasting:</strong> Python analytics service implements Moving Average, Exponential Smoothing and Trend Projection. Where suitable history exists, rolling-origin evaluation compares errors using MAE and RMSE. Model recommendations are conditional, not claims of field accuracy.</p><div class="analytics-method"><span>Historical usage</span>→<span>Compare models</span>→<span>Evaluate errors</span>→<span>Support planning</span></div><div class="asset-panel"><strong>Operational heat map</strong><span>Approved screenshot will be placed here after asset review.</span></div>','analytics')
qa=[('86 / 86','Functional test cases'),('22 / 22','PWA test cases'),('23 / 23','Security test cases'),('72 / 72','Accepted UAT cases')]
distync+=detail_section('05 / QUALITY ASSURANCE','Tested, evaluated, and improved','<p>Our manuscript reports the following results under controlled disaster-response scenarios, not production-service guarantees.</p><div class="qa-grid">'+''.join(f'<div class="qa-stat"><strong>{v}</strong><span>{l}</span></div>' for v,l in qa)+'</div><p>Across <strong>15 participants</strong>, 72 UAT cases were accepted. The reported System Usability Scale mean was <strong>67.17</strong>, just below the benchmark of 68.</p><div class="insight-note">'+icon('shield')+'<span>Passing defined test cases does not mean the system is fully secure or already field-deployed for live disaster operations.</span></div>','testing')
distync+=detail_section('06 / REFLECTION','What I would improve next','<p>Before wider adoption, DISTYNC needs continued usability refinement, real-world field validation, stronger protection for sensitive locally stored data, and tested backup and recovery practices.</p>')
distync+='</article><aside class="study-sidebar"><div class="sidebar-card"><span class="small-label">WHO IT SUPPORTS</span><ul><li>Barangay officials — registration and distribution</li><li>MSWDO — monitoring, analytics and reports</li><li>Mayor\'s Office — inventory and forecasting</li><li>Donors / NGOs — public read-only information</li></ul></div><div class="sidebar-card sidebar-soft"><span class="small-label">BEHIND THE SYSTEM</span><div class="side-pills">'+''.join(f'<span class="pill">{x}</span>' for x in ['React + Vite','Node / Express','PostgreSQL','Supabase','Python / FastAPI','PWA'])+'</div></div><div class="sidebar-card"><span class="small-label">PROJECT SOURCE</span><p>Team repository available after permission and privacy review.</p></div></aside></div><a class="next-project" href="../lost-and-found/index.html"><span>Next project</span><strong>Campus Lost & Found '+icon('upRight')+'</strong></a>'
(preview/'projects/distync/index.html').write_text(start('DISTYNC',base)+header(base)+'<main id="top" class="container study-layout">'+breadcrumb(base,'DISTYNC')+distync+'</main>'+footer()+end())

lost=study_header('02 / INDIVIDUAL PROJECT','Campus Lost & Found: Making it easier to reconnect people and belongings.','A full-stack campus application to report lost or found items, browse listings, and submit ownership claims—with AI-assisted report review.','pink',['Full-stack development','API integration','Software testing','Gemini AI'])
lost+='<div class="study-overview"><div><span class="small-label">PROJECT TYPE</span><strong>Individual project</strong></div><div><span class="small-label">FRONTEND</span><strong>React · TypeScript · Vite</strong></div><div><span class="small-label">BACKEND</span><strong>Express · MongoDB · Gemini API</strong></div></div><div class="study-grid"><article class="study-body">'
lost+=detail_section('01 / THE PROBLEM','A more organized way to look for lost items','<p>Campus lost-and-found reports can be scattered or incomplete. This project explores a clearer user journey: report an item, browse reports, and submit a claim supported by relevant ownership information.</p>')
lost+=detail_section('02 / MY ROLE','Built across the stack','<p>I developed the frontend and backend, connected routes and REST APIs to MongoDB, and implemented authentication, protected claim workflows, form validation, and Gemini-powered report review. I used Codex as a development assistant.</p><div class="journey-grid"><div><span>01</span><strong>Report</strong><p>Submit item details using validated forms.</p></div><div><span>02</span><strong>Browse</strong><p>Explore lost and found listings.</p></div><div><span>03</span><strong>Claim</strong><p>Provide ownership information.</p></div></div>')
lost+=detail_section('03 / ARCHITECTURE','From interface to services','<p>The React frontend communicates with an Express API, which manages access to MongoDB through Mongoose and integrates Gemini for report-review assistance.</p><div class="workflow-card"><div class="workflow-card-top"><strong>Application architecture</strong><a class="diagram-open" href="../../diagrams/lost-found-architecture.svg" target="_blank">Open full diagram</a></div><div class="workflow-image-viewport"><img src="../../diagrams/lost-found-architecture.svg" alt="Browser to React frontend to Express API, connected to MongoDB and Gemini API."></div><p>Diagram adapted from the application README.</p></div>')
lost+=detail_section('04 / QUALITY','Testing, iteration, and deployment','<p>The frontend repository documents Vitest tests, linting, production builds, and GitHub Actions CI. I used AI tools for selected development tasks while reviewing the implementation and behavior.</p>')
lost+=detail_section('05 / REFLECTION','What the project taught me','<p>Building the complete user journey strengthened my understanding of how frontend decisions, API contracts, data modeling, and reliability shape the user experience.</p>')
lost+='</article><aside class="study-sidebar"><div class="sidebar-card"><span class="small-label">SOURCE CODE</span><a class="source-link" href="https://github.com/JaneAllysonParay/itelect4-project" target="_blank" rel="noopener noreferrer">'+icon('github')+' Frontend repository '+icon('upRight')+'</a><a class="source-link" href="https://github.com/JaneAllysonParay/itelect4-backend" target="_blank" rel="noopener noreferrer">'+icon('github')+' Backend repository '+icon('upRight')+'</a></div><div class="sidebar-card sidebar-soft"><span class="small-label">TOOLS & TECHNOLOGIES</span><div class="side-pills">'+''.join(f'<span class="pill">{x}</span>' for x in ['React','TypeScript','Express','MongoDB','Gemini API','Vitest','Vercel'])+'</div></div></aside></div><a class="next-project" href="../distync/index.html"><span>Other featured project</span><strong>DISTYNC '+icon('upRight')+'</strong></a>'
(preview/'projects/lost-and-found/index.html').write_text(start('Campus Lost & Found',base)+header(base)+'<main id="top" class="container study-layout">'+breadcrumb(base,'Campus Lost & Found')+lost+'</main>'+footer()+end())
print('Created static preview files')
